def _ops(s):
    # All strings obtainable from s by exactly one operation
    # (no change, one insertion, one deletion, or one substitution).
    res = {s}
    for i in range(len(s) + 1):
        for c in LETTERS:
            res.add(s[:i] + c + s[i:])
    for i in range(len(s)):
        res.add(s[:i] + s[i + 1:])
        for c in LETTERS:
            res.add(s[:i] + c + s[i + 1:])
    return res


