from hypothesis import strategies as st


def _mutate(draw, s):
    op = draw(st.sampled_from(["keep", "insert", "delete", "change"]))
    if op == "keep" or (op == "delete" and len(s) <= 1):
        return s
    if op == "insert":
        i = draw(st.integers(0, len(s)))
        c = draw(st.sampled_from("ab"))
        return s[:i] + c + s[i:]
    if op == "delete":
        i = draw(st.integers(0, len(s) - 1))
        return s[:i] + s[i + 1:]
    i = draw(st.integers(0, len(s) - 1))
    c = draw(st.sampled_from("ab"))
    return s[:i] + c + s[i + 1:]


