def _ok(s, tp):
    # Could T equal s, given T' = tp was obtained from T by at most one edit?
    if s == tp:
        return True
    if len(tp) == len(s) + 1:
        # tp is s with one char inserted: deleting some char of tp yields s
        return any(tp[:i] + tp[i + 1:] == s for i in range(len(tp)))
    if len(tp) == len(s) - 1:
        # tp is s with one char deleted: deleting some char of s yields tp
        return any(s[:i] + s[i + 1:] == tp for i in range(len(s)))
    if len(tp) == len(s):
        return sum(1 for a, b in zip(s, tp) if a != b) == 1
    return False


